// ===========================================
// Expense Tracking Agent - Code Node
// Purpose:
// Extract expense details from WhatsApp message
// ===========================================

// Get incoming message
const message =
  $json.messages?.[0]?.text?.body ||
  $json.body ||
  "";

// -------------------------------------------
// Date & Time
// -------------------------------------------
const now = new Date();

const date = now.toLocaleDateString("en-GB"); // DD/MM/YYYY

const time = now.toLocaleTimeString("en-IN", {
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: true
});

// -------------------------------------------
// Amount
// -------------------------------------------
const amountMatch = message.match(/(?:₹|Rs\.?|INR)?\s*([\d,]+(?:\.\d{1,2})?)/i);

const amount = amountMatch
  ? Number(amountMatch[1].replace(/,/g, ""))
  : "";

// -------------------------------------------
// Currency
// -------------------------------------------
let currency = "INR";

if (/\$/.test(message)) currency = "USD";
else if (/€/.test(message)) currency = "EUR";
else if (/£/.test(message)) currency = "GBP";

// -------------------------------------------
// Payment Method
// -------------------------------------------
let paymentMethod = "Unknown";

const paymentMethods = {
  "Google Pay": /gpay|google pay/i,
  "PhonePe": /phonepe/i,
  "Paytm": /paytm/i,
  "UPI": /\bupi\b/i,
  "Credit Card": /credit card/i,
  "Debit Card": /debit card/i,
  "Card": /\bcard\b/i,
  "Cash": /\bcash\b/i,
  "Net Banking": /net banking/i
};

for (const [method, regex] of Object.entries(paymentMethods)) {
  if (regex.test(message)) {
    paymentMethod = method;
    break;
  }
}

// -------------------------------------------
// Category Detection
// -------------------------------------------
const categories = {
  Food: ["food","restaurant","pizza","burger","cafe","coffee","tea","swiggy","zomato"],
  Transport: ["uber","ola","petrol","diesel","fuel","bus","train","auto","taxi"],
  Shopping: ["shopping","shirt","shoe","shoes","clothes","jeans","amazon","flipkart","mall"],
  Grocery: ["grocery","vegetable","fruit","milk","dmart"],
  Bills: ["bill","electricity","wifi","internet","recharge","mobile"],
  Entertainment: ["movie","cinema","netflix","spotify","game"],
  Health: ["medicine","hospital","doctor","medical","pharmacy"],
  Education: ["course","book","fees","college","exam"]
};

let category = "Others";

const lowerMessage = message.toLowerCase();

for (const [cat, keywords] of Object.entries(categories)) {
  if (keywords.some(word => lowerMessage.includes(word))) {
    category = cat;
    break;
  }
}

// -------------------------------------------
// Merchant / Item
// -------------------------------------------
let merchant = message
  .replace(/(?:₹|Rs\.?|INR)?\s*[\d,]+(?:\.\d{1,2})?/gi, "")
  .replace(/spent|paid|bought|purchase|for|on|using|via/gi, "")
  .replace(/cash|upi|gpay|google pay|phonepe|paytm|credit card|debit card|card|net banking/gi, "")
  .replace(/\s+/g, " ")
  .trim();

if (!merchant) merchant = "Unknown";

// -------------------------------------------
// Status
// -------------------------------------------
const status = amount ? "Recorded" : "Need Confirmation";

// -------------------------------------------
// Output
// -------------------------------------------
return [
  {
    json: {
      date,
      time,
      original_message: message,
      amount,
      currency,
      category,
      merchant,
      payment_method: paymentMethod,
      status
    }
  }
];

// ===========================================
// Expense Tracking Agent
// Calculate Total Expenses & Generate Summary
// ===========================================

// Get all rows from Google Sheets
const rows = $input.all();

let totalExpense = 0;
let totalTransactions = 0;

const expenseList = [];

// Process each row
for (const item of rows) {

    const data = item.json;

    const amount = Number(data.amount) || 0;

    totalExpense += amount;
    totalTransactions++;

    expenseList.push(
        `• ${data.date} | ${data.category} | ₹${amount}`
    );
}

// Format total
const formattedTotal = totalExpense.toLocaleString("en-IN");

// Prepare WhatsApp Message
const whatsappMessage = `💰 *Expense Summary*

━━━━━━━━━━━━━━━━━━

📊 Total Transactions : ${totalTransactions}

💵 Total Expenses : ₹${formattedTotal}

━━━━━━━━━━━━━━━━━━

🧾 *Expense History*

${expenseList.join("\n")}

━━━━━━━━━━━━━━━━━━

✅ Your expenses have been updated successfully.`;

return [
  {
    json: {
      total_transactions: totalTransactions,
      total_expenses: totalExpense,
      whatsapp_message: whatsappMessage
    }
  }
];

